import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"分镜设计：镜头语言翻译表","description":"","frontmatter":{},"headers":[],"relativePath":"method/storyboard.md","filePath":"method/storyboard.md","lastUpdated":1787714366000}'),o={name:"method/storyboard.md"};function h(l,t,s,i,n,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="分镜设计-镜头语言翻译表" tabindex="-1">分镜设计：镜头语言翻译表 <a class="header-anchor" href="#分镜设计-镜头语言翻译表" aria-label="Permalink to &quot;分镜设计：镜头语言翻译表&quot;">​</a></h1><p>这一篇解决一个具体问题：<strong>你脑子里的画面，怎么翻译成模型听得懂的话。</strong></p><p>「我想要有电影感」——模型不知道你要什么。「35mm 镜头，浅景深，侧逆光，暖色调，手持轻微晃动」——模型知道。</p><h2 id="四组必须写清楚的参数" tabindex="-1">四组必须写清楚的参数 <a class="header-anchor" href="#四组必须写清楚的参数" aria-label="Permalink to &quot;四组必须写清楚的参数&quot;">​</a></h2><p>任何一个镜头，至少要交代这四件事。缺一件，模型就会自由发挥，而自由发挥的结果通常不是你要的。</p><h3 id="一、景别-镜头离主体多远" tabindex="-1">一、景别：镜头离主体多远 <a class="header-anchor" href="#一、景别-镜头离主体多远" aria-label="Permalink to &quot;一、景别：镜头离主体多远&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文</th><th>英文关键词</th><th>画面范围</th><th>主要用途</th></tr></thead><tbody><tr><td>大远景</td><td>extreme wide shot</td><td>人在画面里很小</td><td>交代环境、营造孤独或宏大</td></tr><tr><td>远景</td><td>wide shot</td><td>全身 + 大量环境</td><td>交代场景关系</td></tr><tr><td>全景</td><td>full shot</td><td>全身刚好入画</td><td>展示动作</td></tr><tr><td>中景</td><td>medium shot</td><td>腰部以上</td><td>对话、常规叙事</td></tr><tr><td>近景</td><td>close-up</td><td>肩部以上</td><td>表情、情绪</td></tr><tr><td>特写</td><td>extreme close-up</td><td>眼睛、手、产品局部</td><td>强调细节、制造张力</td></tr></tbody></table><p><strong>产品广告的经验值</strong>：产品特写至少占全片镜头数的三分之一。观众记不住故事，但记得住那个反光的瓶身。</p><h3 id="二、机位与角度-从哪儿看" tabindex="-1">二、机位与角度：从哪儿看 <a class="header-anchor" href="#二、机位与角度-从哪儿看" aria-label="Permalink to &quot;二、机位与角度：从哪儿看&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文</th><th>英文关键词</th><th>心理效果</th></tr></thead><tbody><tr><td>平视</td><td>eye level</td><td>中性、平等</td></tr><tr><td>俯拍</td><td>high angle / top-down</td><td>弱小、被审视、全局感</td></tr><tr><td>仰拍</td><td>low angle</td><td>高大、有力量、有压迫感</td></tr><tr><td>过肩</td><td>over the shoulder</td><td>代入感、对话感</td></tr><tr><td>主观视角</td><td>POV shot</td><td>强代入，适合竖屏短视频</td></tr><tr><td>荷兰角</td><td>dutch angle</td><td>不安、失衡</td></tr></tbody></table><p><strong>竖屏短视频的经验值</strong>：主观视角和特写最有效，因为屏幕小，中远景里的信息看不清。</p><h3 id="三、光线-这是质感的主要来源" tabindex="-1">三、光线：这是质感的主要来源 <a class="header-anchor" href="#三、光线-这是质感的主要来源" aria-label="Permalink to &quot;三、光线：这是质感的主要来源&quot;">​</a></h3><p>多数「AI 素材看起来廉价」的问题，根源是光。默认生成的画面往往是平光——均匀、无方向、无层次，像证件照。</p><table tabindex="0"><thead><tr><th>中文</th><th>英文关键词</th><th>效果</th></tr></thead><tbody><tr><td>侧逆光</td><td>rim light / backlight</td><td>主体有轮廓光，最出质感，产品广告首选</td></tr><tr><td>侧光</td><td>side light</td><td>立体感强，有明暗对比</td></tr><tr><td>顺光</td><td>front light</td><td>平、清晰、无氛围</td></tr><tr><td>顶光</td><td>top light</td><td>硬朗、戏剧化</td></tr><tr><td>柔光</td><td>soft light / diffused</td><td>温柔、无硬阴影，美妆常用</td></tr><tr><td>硬光</td><td>hard light</td><td>阴影边缘锐利，力量感</td></tr><tr><td>黄金时刻</td><td>golden hour</td><td>暖、低角度、氛围感强</td></tr><tr><td>蓝调时刻</td><td>blue hour</td><td>冷、安静、都市感</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一条经验</p><p>拿不准的时候写 <code>soft rim light</code>（柔和轮廓光）。它几乎不会出错，能给主体一圈光边把它从背景里&quot;抠&quot;出来，立刻显得贵。</p></div><h3 id="四、运镜-画面怎么动-视频专用" tabindex="-1">四、运镜：画面怎么动（视频专用） <a class="header-anchor" href="#四、运镜-画面怎么动-视频专用" aria-label="Permalink to &quot;四、运镜：画面怎么动（视频专用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文</th><th>英文关键词</th><th>用途</th></tr></thead><tbody><tr><td>固定</td><td>static shot</td><td>稳定、正式</td></tr><tr><td>推</td><td>dolly in / push in</td><td>聚焦、情绪递进</td></tr><tr><td>拉</td><td>dolly out / pull back</td><td>揭示环境、收尾</td></tr><tr><td>横移</td><td>tracking shot / pan</td><td>跟随、展示</td></tr><tr><td>环绕</td><td>orbit shot</td><td>产品展示的万能镜头</td></tr><tr><td>手持</td><td>handheld</td><td>真实感、纪实感、UGC 风</td></tr><tr><td>升格</td><td>slow motion</td><td>强调质感（液体、飘落物）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">视频模型的运镜服从度有限</p><p>运镜描述属于「建议」而非「指令」。给一个明确的运镜词能提高命中率，但写一串复杂的复合运镜（&quot;先推再左移然后上摇&quot;）基本不会实现。<strong>一个镜头只给一个运镜。</strong></p><p>具体到某个模型能实现多复杂的运镜，以官网和实测为准——这项能力迭代很快。</p></div><h2 id="一个完整的分镜表长什么样" tabindex="-1">一个完整的分镜表长什么样 <a class="header-anchor" href="#一个完整的分镜表长什么样" aria-label="Permalink to &quot;一个完整的分镜表长什么样&quot;">​</a></h2><p>以一支 15 秒竖屏速食早餐广告为例：</p><table tabindex="0"><thead><tr><th>#</th><th>时长</th><th>景别</th><th>机位</th><th>主体与动作</th><th>环境</th><th>光</th><th>运镜</th></tr></thead><tbody><tr><td>1</td><td>0–3s</td><td>特写</td><td>平视</td><td>闹钟屏幕数字跳到 7:42，手伸进来按掉</td><td>昏暗卧室床头</td><td>窗帘缝隙透进的硬光</td><td>固定</td></tr><tr><td>2</td><td>3–5s</td><td>近景</td><td>俯拍</td><td>年轻人趴在床上不动，眼睛睁着</td><td>凌乱的床</td><td>冷调环境光</td><td>缓慢推近</td></tr><tr><td>3</td><td>5–7s</td><td>中景</td><td>平视</td><td>冲进厨房，打开冰箱，光打在脸上</td><td>小户型厨房</td><td>冰箱内光为主光源</td><td>手持轻晃</td></tr><tr><td>4</td><td>7–10s</td><td>特写</td><td>平视</td><td>产品包装被拿起，撕开</td><td>台面</td><td>侧逆光，轮廓清晰</td><td>固定</td></tr><tr><td>5</td><td>10–13s</td><td>特写</td><td>微俯</td><td>热食冒出蒸汽，质感细节</td><td>餐盘</td><td>侧逆光 + 暖色</td><td>升格</td></tr><tr><td>6</td><td>13–15s</td><td>中景</td><td>平视</td><td>人边走边吃，出门，表情松弛</td><td>玄关</td><td>门外自然光</td><td>拉远</td></tr></tbody></table><p>**每一行都能直接翻译成一条 Prompt。**这就是分镜表的价值——它把&quot;做一支广告&quot;这个模糊任务，变成了六个明确的、可以并行执行的小任务。</p><p>具体的翻译方法见 <a href="/prompts/video-storyboard">短视频分镜脚本 Prompt</a>。</p><h2 id="分镜的三条结构原则" tabindex="-1">分镜的三条结构原则 <a class="header-anchor" href="#分镜的三条结构原则" aria-label="Permalink to &quot;分镜的三条结构原则&quot;">​</a></h2><h3 id="原则一-前-3-秒必须有异常" tabindex="-1">原则一：前 3 秒必须有异常 <a class="header-anchor" href="#原则一-前-3-秒必须有异常" aria-label="Permalink to &quot;原则一：前 3 秒必须有异常&quot;">​</a></h3><p>竖屏信息流里，观众滑动的决定在 1 秒内做出。第一个镜头如果是&quot;美好的清晨阳光洒进房间&quot;，滑走。它必须有一点不对劲——一个反常的数字、一个奇怪的角度、一个没说完的动作。</p><h3 id="原则二-相邻镜头要变化" tabindex="-1">原则二：相邻镜头要变化 <a class="header-anchor" href="#原则二-相邻镜头要变化" aria-label="Permalink to &quot;原则二：相邻镜头要变化&quot;">​</a></h3><p>连续两个镜头如果景别相同、机位相同、光线相同，观众会感觉画面&quot;没动&quot;。**至少变一个参数。**上面的分镜表里，特写—近景—中景—特写—特写—中景，每一跳都有变化。</p><h3 id="原则三-产品出现不能太晚-也不能太早" tabindex="-1">原则三：产品出现不能太晚，也不能太早 <a class="header-anchor" href="#原则三-产品出现不能太晚-也不能太早" aria-label="Permalink to &quot;原则三：产品出现不能太晚，也不能太早&quot;">​</a></h3><p>太早（第一个镜头就是产品）像硬广，观众直接划走。太晚（12 秒后才出现）观众已经忘了这是广告，记不住品牌。</p><p>**经验区间：总时长的 40%–60% 之间首次出现产品。**15 秒的片子，6–9 秒之间。上表里产品在第 7 秒出现，符合。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>「分镜要画出来吗？」</strong> 不需要。文字分镜表已经足够，因为下游是文本驱动的生成模型。想要可视化，可以先用图像模型把每个镜头生成一张静帧当作故事板，成本很低，且能提前发现风格问题。</p><p><strong>「镜头数量怎么定？」</strong> 经验值：<strong>每个镜头 2–3 秒</strong>。15 秒对应 5–7 个镜头，30 秒对应 10–14 个。镜头过少会显得拖沓，过多会来不及看清。</p><p><strong>「AI 生成的镜头时长不好控制怎么办？」</strong> 生成时不必纠结精确时长，多生成一点素材，在剪辑阶段裁到需要的长度。这比反复重生成划算得多。</p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>把分镜翻译成 Prompt → <a href="/prompts/video-storyboard">短视频分镜脚本</a></li><li>Prompt 的通用写法 → <a href="/prompts/structure">Prompt 结构通法</a></li></ul>',37)])])}const c=d(o,[["render",h]]);export{u as __pageData,c as default};
